import { ChangeDetectorRef, Component, Input } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatMenuModule } from '@angular/material/menu';
import { MatExpansionModule } from '@angular/material/expansion';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { BadgeComponent } from '../../../shared/components/badge/badge.component';
import { TaskTableComponent } from '../../../shared/components/task-table/task-table.component';
import { HeaderService } from '../../../core/services/header/header.service';
import { CasedetailService } from '../../../shared/services/casedetail/casedetail.service';
import { TaskService } from '../../../shared/services/task/task.service';
import { IssuecategoryRes } from '../../interfaces/task.interface';
import { TaskpopupComponent } from '../taskpopup/taskpopup.component';
import { MatDialog } from '@angular/material/dialog';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { EmptyComponent } from '../../../shared/components/empty/empty.component';
import { CommonService } from '../../../shared/services/common/common.service';
import { Subject, map } from 'rxjs';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { finalFilterList } from '../../../shared/interfaces/filter.interface';
import { FiltersComponent } from '../../../shared/components/filters/filters.component';
import { SkeletonComponent } from '../../../shared/components/skeleton/skeleton.component';
import { UserPermissionService } from '../../../shared/services/user-permission/user-permission.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';

@Component({
  selector: 'app-task',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, MatTooltipModule, MatMenuModule, MatExpansionModule, BadgeComponent, TaskTableComponent, EmptyComponent,
    FiltersComponent, SkeletonComponent
  ],
  templateUrl: './task.component.html',
  styleUrl: './task.component.scss'
})
export class TaskComponent {
  nCaseid: string;

  viewlist: any = [
    { tab: 'F', 'cName': 'Fact Task' },
    { tab: 'C', 'cName': 'File Task' },
  ];

  tablecols: any = [{ id: 1, 'name': 'Creator', 'key': 'Creator', 'isshow': true },
  { id: 2, 'name': 'Assignee', 'key': 'Assignee', 'isshow': true },
  { id: 3, 'name': 'Priority', 'key': 'Priority', 'isshow': true },
  { id: 4, 'name': 'Progress', 'key': 'Progress', 'isshow': true },
  { id: 5, 'name': 'Timeline', 'key': 'Timeline', 'isshow': true },
  { id: 6, 'name': 'Reminder', 'key': 'Reminder', 'isshow': true }
  ];

  issue_ls: IssuecategoryRes[] = []
  filetask: any = []

  activetab = 'F';
  showcolalert: boolean = false;
  loading: boolean = false;
  @Input() onTaskspaceEvent: Subject<toolEvents>;
  showfilter: boolean = false;
  jFilter: finalFilterList[] = [];
  isFiltered: boolean = false;
  constructor(private hs: HeaderService,
    private cDetailS: CasedetailService, private route: ActivatedRoute,
    private taskservice: TaskService, private dialog: MatDialog,
    private cdr: ChangeDetectorRef, private cs: CommunicationService,
    private tost: TostbarService, private common: CommonService,
    private userPermissions: UserPermissionService, private cf: CommonfunctionService) {

    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    userPermissions.userPermissionList(this.nCaseid);
  }

  async ngOnInit() {
    this.hs.nCaseid = this.nCaseid;
    this.hs.Casedetail = await this.cDetailS.getCaseInfo(this.nCaseid);
    this.getIssueList();
    this.cdr.detectChanges()
  }


  opentask(x?) {
    const dialogRef = this.dialog.open(TaskpopupComponent, {
      data: 'E',
      width: '80%',
      height: '95vh',
    });
    dialogRef.componentInstance.nCaseid = this.nCaseid;
    dialogRef.componentInstance.detail = x;
    dialogRef.componentInstance.permission = x ? 'E' : 'N';
    dialogRef.componentInstance.activetab = this.activetab;
    dialogRef.afterClosed().subscribe(result => {
      if (result == 'SUBMIT') {
        if (this.activetab == 'F') {
          this.getIssueList();
        } else {
          this.getFileIssueList();
        }
      }
    });
  }


  changeTab(x) {
    if(this.activetab != x.tab){
      this.activetab = x.tab;
      this.jFilter = [];
      this.isFiltered = false;
      this.getFileIssueList();
    }
  }


  async getIssueList() {
    this.loading = true;
    const res = await this.taskservice.get_sidenavIssue(this.nCaseid, this.jFilter);
    this.issue_ls = this.groupIssueCategory(res);
    this.loading = false;
  }

  async getFileIssueList() {
    this.loading = true;
    const res = await this.taskservice.get_sidenavTask(this.nCaseid, this.jFilter);
    this.filetask = res[0] ? res[0] : [];
    let teamlist = res[1] ? res[1] : [];
    let reminders = res[2] ? res[2] : [];
    this.loading = false;
    this.filetask.forEach(async element => {
      element.teamlist = teamlist.filter(y => y.jTaskid.includes(element.nTaskid));
      let reminder = reminders.filter(y => y.nTaskid === element.nTaskid);
      element.jReminders = reminder && reminder.length && reminder[0].jReminders ? reminder[0].jReminders : []
    })
  }


  groupIssueCategory(issues) {
    let issuecategory: IssuecategoryRes[] = [];
    issues.forEach(element => {
      if (!issuecategory.length) {
        issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
      } else {
        const index = issuecategory.findIndex(e => e.nICid == element.nICid);
        if (index > -1) {
          issuecategory[index].sublist.push(element);
        } else {
          issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
        }
      }
    });
    return issuecategory;
  }

  resetTable() {
    this.tablecols.map(x => x.isshow = true);
    this.cs.callFunction({ type: 'SHOW-COLS_TASK', tablecols: this.tablecols });
  }


  changeTabcols(x) {
    if (x.isshow == true && this.tablecols.filter(x => x.isshow == true).length <= 3) { this.showcolalert = true; return }
    x.isshow = !x.isshow;
    this.showcolalert = false;
    this.cs.callFunction({ type: 'SHOW-COLS_TASK', tablecols: this.tablecols });
  }

  async checkCompletedTask(list) {
    return list.filter(x => x?.cStatus == 'C').length > 0 ? true : false;
  }

  async getTask(x) {
    const res = await this.taskservice.get_sidenavTaskByissue(this.nCaseid, x.nIssueid);
    x.taskls = res[0] ? res[0] : [];
    let teamlist = res[1] ? res[1] : [];
    let reminders = res[2] ? res[2] : [];
    x.taskls.forEach(async element => {
      element.teamlist = teamlist.filter(y => y.jTaskid.includes(element.nTaskid));
      let reminder = reminders.filter(y => y.nTaskid === element.nTaskid);
      element.jReminders = reminder && reminder.length && reminder[0].jReminders ? reminder[0].jReminders : []
    })

  }

  onChange(event, x) {
    debugger;
    if (event.event == 'delete') {
      if (this.activetab == 'F') {
        this.deleteFactTask(x.nTaskid, x.nFSid);
      } else {
        this.delete(x.nTaskid);
      }
    }
    if (event.event == 'EDIT') {
      this.opentask(x);
    }
    if (event.event == 'VIEW_FILE') {
      this.openFactLink(event.data);
    }
  }


  delete(nTaskid) {
    this.taskservice.deleteTask({ nTaskid: nTaskid }).then(res => {
      if (res[0]["msg"] == 1) {
        if (this.activetab == 'F') {
          this.issue_ls = this.issue_ls.map(x => {
            x.sublist.filter(y => y.isOpen).map(y => {
              y.taskls = y.taskls.filter(z => z.nTaskid != nTaskid);
            });
            return x;
          });
        } else {
          this.filetask = this.filetask.filter(x => x.nTaskid != nTaskid);
        }
        this.cdr.detectChanges();
      } else {
        this.tost.openSnackBar(res[0]["value"], 'E');
      }
    }
    );
  }


  deleteFactTask(nTaskid, nFSid?: number) {

    if (this.activetab == 'F') {
      this.taskservice.deleteFactTask({ nTaskid: nTaskid, nFSid: nFSid }).then(res => {
        if (res[0]["msg"] == 1) {
          this.issue_ls = this.issue_ls.map(x => {
            x.sublist.filter(y => y.isOpen).map(y => {
              let ind = y.taskls.findIndex(z => z.nTaskid == nTaskid && z.nFSid == nFSid);
              if (ind > -1) {
                // y.taskls[ind].isOpen = false;
                y.taskls.splice(ind, 1);
              }
            });
            return x;
          });
        } else {
          this.tost.openSnackBar(res[0]["value"], 'E');
        }
      });
    }
    //  else {

    //   this.taskservice.deleteFileTask({ nTaskid: nTaskid, nBundledetailid: nBundledetailid }).then(res => {
    //     if (res[0]["msg"] == 1) {
    //       let ind = this.filetask.findIndex(x => x.nTaskid == nTaskid && x.nBundledetailid == nBundledetailid);
    //       if (ind > -1) {
    //         this.filetask.splice(ind, 1);
    //       }
    //       // this.filetask = this.filetask.filter(x => x.nTaskid != nTaskid);
    //     } else {
    //       this.tost.openSnackBar(res[0]["value"], 'E');
    //     }
    //   });
    // }
    this.cdr.detectChanges();

  }


  OnFilterResult(e: toolEvents) {

    if (e.event == 'FILTER') {
      this.jFilter = e.data;
      this.isFiltered = e.data?.length;
      if (this.activetab == 'F') {
        this.getIssueList();
      } else {
        this.getFileIssueList();
      }
      this.cdr.detectChanges();
    } else if (e.event == 'BACK') {
      this.showfilter = false;
      this.cdr.detectChanges();
    }
  }

  openFactLink(data) {
    if (!data.nBundledetailid) return;
    let nPage = data.nPage || 1
    this.cf.openHyperLinkFile(data.nBundledetailid, this.nCaseid, null, null, false, nPage)
  }

}
