import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { ButtonComponent } from '../button/button.component';
import { IconComponent } from '../icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { CommonModule } from '@angular/common';
import { AvatarComponent } from '../avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { SharedViewComponent } from '../shared-view/shared-view.component';
import { BadgeComponent } from '../badge/badge.component';
import { SelectedIssuesComponent } from '../issues/selected-issues/selected-issues.component';
import { SelectedContactComponent } from '../contacts/selected-contact/selected-contact.component';
import { SourceCardComponent } from '../source-card/source-card.component';
import { factIssues, factlinkfiles, headerColumns, taskupdateRes } from '../../interfaces/fact.interface';
import { TaskService } from '../../services/task/task.service';
import { FactService } from '../../services/fact/fact.service';
import { myTeamUsers, toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { selectedContactList } from '../../interfaces/issue.interface';
import { CommunicationService } from '../../services/communication/communication.service';
import { Subscription } from 'rxjs';
import { FactboxComponent } from '../../../pdf/components/facts/factbox/factbox.component';
import { MatSliderModule } from '@angular/material/slider';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-task-table',
  standalone: true,
  imports: [CommonModule, ButtonComponent, IconComponent, MatMenuModule, AvatarComponent, MatTooltipModule, SharedViewComponent, BadgeComponent, SelectedIssuesComponent, SelectedContactComponent, SourceCardComponent, FactboxComponent, MatMenuModule, MatSliderModule,
    MatButtonModule,
    MatIconModule,
    FormsModule
  ],
  templateUrl: './task-table.component.html',
  styleUrl: './task-table.component.scss'
})
export class TaskTableComponent {
  @Input() detail: any = {};
  @Input() isFile: boolean = false;
  @Output() onChange: EventEmitter<toolEvents> = new EventEmitter();
  showReview: boolean = false;
  factdetail: any = {};
  filelist: any = [];


  up_icon: any = '../../../../assets/img/sortup.svg';
  down_icon: any = '../../../../assets/img/sortdown.svg';
  group_icon: any = '../../../../assets/img/groupby.svg';



  sourceData: any = {}
  issueList: factIssues[] = [];
  linkfiles: factlinkfiles[] = [];
  userList: myTeamUsers[] = [];
  selectedUsr: myTeamUsers[] = [];
  contactlist: selectedContactList[] = [];

  jTexts: string[] = []
  @Input() tablecols: any = [];
  headercoloumns: headerColumns[] = [
    { id: 1, isshow: true, name: 'Creator', sortlist: [{ nm: 'Most recent', icon: this.up_icon, typ: 'A', clmn: 'dCreateDt' }, { nm: 'Oldest', icon: this.down_icon, typ: 'D', clmn: 'dCreateDt' }] },
    { id: 2, isshow: true, name: 'Assignee', sortlist: [] },
    { id: 3, isshow: true, name: 'Priority', sortlist: [] },
    { id: 4, isshow: true, name: 'Progress', sortlist: [{ nm: 'Most relevance', icon: this.up_icon, typ: 'A', clmn: 'toprelevance_ind' }, { nm: 'Least relevance', icon: this.down_icon, typ: 'D', clmn: 'toprelevance_ind' }, { nm: 'Group by this column', icon: this.group_icon, typ: 'G', clmn: 'R' }] },
    { id: 5, isshow: true, name: 'Timeline', sortlist: [{ nm: 'Most impact', icon: this.up_icon, typ: 'A', clmn: 'topimpact_ind' }, { nm: 'Least impact', icon: this.down_icon, typ: 'D', clmn: 'topimpact_ind' }, { nm: 'Group by this column', icon: this.group_icon, typ: 'G', clmn: 'I' }] },
    { id: 6, isshow: true, name: 'Reminder', sortlist: [{ nm: 'A-Z', icon: this.up_icon, typ: 'A', clmn: 'cFilename' }, { nm: 'Z-A', icon: this.down_icon, typ: 'D', clmn: 'cFilename' }, { nm: 'Group by this column', icon: this.group_icon, typ: 'G', clmn: 'F' }] },
  ];

  evsubscription: Subscription;
  nProgress: number = 0;

  constructor(
    private factservice: FactService,
    private task: TaskService,
    private cdr: ChangeDetectorRef, private cs: CommunicationService,
  ) {
    this.evsubscription = this.cs.functionCalled$.subscribe(async (data) => {
      if (data.type == 'SHOW-COLS_TASK') {
        if (this.headercoloumns && this.headercoloumns.length) {
          this.headercoloumns = this.headercoloumns.map(a => {
            a.isshow = data.tablecols.filter(b => b.id == a.id)[0].isshow;
            return a;
          });
        }
        this.cdr.detectChanges();
      }
    });
  }
  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    if (this.tablecols && this.tablecols.length) {
      this.headercoloumns = this.headercoloumns.map(a => {
        a.isshow = this.tablecols.filter(b => b.id == a.id)[0].isshow;
        return a;
      });
    }

    if (this.detail) {
      this.nProgress = this.detail.nProgress || 0;
    }
  }

  async getFact(y) {
    const res = await this.factservice.getFactDetails([y.nFSid]);
    this.factdetail = res[0] ? res[0] : {};
    this.jTexts = this.factdetail.jTexts ? this.factdetail.jTexts : [];
    this.fetchIssuesAndLinks(y.nFSid);
    this.fetchSharedList(y.nFSid);
    this.fetchContactList(y.nFSid);
  }

  ngOnDestroy(): void {
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
    this.evsubscription.unsubscribe();
  }


  async getbundlels(y) {
    const res = await this.factservice.getfiles_bytask(y.nTaskid);
    this.filelist = res
    this.filelist.map(e=>{
      const page = e?.cPage?.split('-');
      e['jLinktype'] = {start: page[0], end: page[1]};
    })
  }

  async fetchIssuesAndLinks(nFSid) {
    const res = await this.factservice.getFactIssuesAndLinks([nFSid]);
    if (res.length) {
      this.issueList = res[0] || []; // .filter(b => b.nFSid == a.nFSid)
      this.linkfiles = res[1] || []; // .filter(b => b.nFSid == a.nFSid)      
      if (this.linkfiles.length) {
        this.linkfiles.forEach(element => {
          if (element?.jLinktype) {
            element.cPageRange = `${element?.jLinktype?.start}-${element?.jLinktype?.end}`
          }
        });
      }
    }
    this.cdr.detectChanges();
  }


  async updateTaskStatus(y, cStatus) {
    const res: taskupdateRes = await this.factservice.updateTaskStatus(y.nTaskid, cStatus);
    if (res && res.msg == 1) {
      y.cStatus = cStatus;
      y.nProgress = cStatus == 'C' ? 100 : cStatus == 'P' ? 0 : y.nProgress;
      this.cdr.detectChanges();
    }
  }


  async fetchSharedList(nFSid) {
    this.selectedUsr = await this.factservice.getFactShare(nFSid);
    this.userList.map(a => a.isSelected = (this.selectedUsr.findIndex(b => b.nUserid == a.nUserid) > -1));
    this.userList = [...this.userList];
    this.cdr.detectChanges();
  }


  async fetchContactList(nFSid) {
    // this.isContactLoaded = false;
    this.cdr.detectChanges();
    this.contactlist = await this.factservice.getFactContact(nFSid);
    // this.isContactLoaded = true;
    this.cdr.detectChanges();
  }


  delete() {
    this.onChange.emit({ event: 'delete', data: this.detail.nTaskid });
  }


  edit() {
    this.onChange.emit({ event: 'EDIT', data: this.detail.nTaskid });
  }

  async saveProgress(menu: any) {
    const params = {
      nTaskid: this.detail.nTaskid,
      nProgress: this.nProgress,
      permission: 'S'
    }
    const res: boolean = await this.task.updateTaskProgress(params);
    if (res) {
      this.detail.nProgress = this.nProgress;
      if (this.nProgress == 100) {
        this.detail.cStatus = 'C';
      }
      menu?.closeMenu();
    }
  }
  viewFile(x) {
    debugger;
    this.onChange.emit({ event: 'VIEW_FILE', data: x });
  }

}
