import { Component, Input, Optional } from '@angular/core';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { CommonModule } from '@angular/common';
import { TaskFormComponent } from '../../../shared/components/tasks/task-form/task-form.component';
import { DoccardComponent } from '../../../shared/components/doccard/doccard.component';
import { FileexplorerComponent } from '../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { MatDialogRef } from '@angular/material/dialog';
import { assignTask } from '../../../shared/interfaces/myfile.interface';
import { MyfileService } from '../../../shared/services/myfile/myfile.service';
import { FactService } from '../../../shared/services/fact/fact.service';

@Component({
  selector: 'app-taskpopup',
  standalone: true,
  imports: [ButtonComponent, CommonModule, TaskFormComponent, DoccardComponent, FileexplorerComponent],
  templateUrl: './taskpopup.component.html',
  styleUrl: './taskpopup.component.scss'
})

export class TaskpopupComponent {
  nCaseid: string;
  permission: string = 'N';
  cuurenttab = 'C';
  filelist: any = [];
  detail: any = {};
  activetab: string = 'F';

  constructor(private mfs: MyfileService, private factservice: FactService,
    @Optional() public MatDialogRef: MatDialogRef<TaskpopupComponent>
  ) { }

  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    if (this.permission === 'E') {
      this.cuurenttab = 'D';
      if (this.activetab === 'F') {
        this.getFact(this.detail);
        return;
      }
      this.getbundlels(this.detail);
    }
  }

  async getFact(y) {
    const res = await this.factservice.getFactDetails(y.nFSid);
    this.filelist = res
  }


  async getbundlels(y) {
    const res = await this.factservice.getfiles_bytask(y.nTaskid);
    this.filelist = res
  }


  FileEvent(event) {
    if (event.event === 'VIEW') {
      this.filelist = event.data;
    }
  }

  cancel() {
    this.MatDialogRef.close();
    console.log('cancel');
  }

  async taskFormRes(event) {
    if (event.event === 'SUBMIT') {
      if (this.permission === 'N') {
        let nTaskid = event.data && event.data.nTaskid ? event.data.nTaskid : null;
        if (nTaskid) {
          const jBDids = this.filelist.map(x => x.nBundledetailid);
          var mdl: assignTask = { nTaskid: nTaskid, jFiles: JSON.stringify(jBDids) };
          const res = await this.mfs.assignTask(mdl);
          if (res) {
            this.MatDialogRef.close('SUBMIT');
          } else {
            // this.getTask();
          }
        }
      } else {
        this.MatDialogRef.close('SUBMIT');
      }

    }
    if (event.event === 'DELETE') {
      this.MatDialogRef.close('SUBMIT');
    }
  }

}
